package com.trombokendu.chronos.persistence;
import java.sql.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import com.trombokendu.chronos.domain.*;
public final class ConnectionPool implements AutoCloseable {
 private final BlockingQueue<Connection> queue;private final AtomicBoolean closed=new AtomicBoolean();
 public ConnectionPool(String url,int size){queue=new ArrayBlockingQueue<>(size);try{for(int i=0;i<size;i++){Connection c=DriverManager.getConnection(url);try(Statement s=c.createStatement()){s.execute("PRAGMA foreign_keys=ON");s.execute("PRAGMA journal_mode=WAL");s.execute("PRAGMA busy_timeout=5000");}queue.add(c);}}catch(SQLException e){throw new PersistenceException("Pool creation failed",e);}}
 public Connection get(){try{if(closed.get())throw new PersistenceException("Pool closed");return new Lease(queue.take());}catch(InterruptedException e){Thread.currentThread().interrupt();throw new PersistenceException("Interrupted waiting for connection",e);}}
 public void close(){closed.set(true);Connection c;while((c=queue.poll())!=null)try{c.close();}catch(SQLException ignored){}}
 private final class Lease extends Wrapper{private boolean returned;Lease(Connection c){super(c);}public void close()throws SQLException{if(!returned){returned=true;if(closed.get()||!queue.offer(delegate))delegate.close();}}}
 private static class Wrapper implements Connection{final Connection delegate;Wrapper(Connection c){delegate=c;}public <T>T unwrap(Class<T>x)throws SQLException{return delegate.unwrap(x);}public boolean isWrapperFor(Class<?>x)throws SQLException{return delegate.isWrapperFor(x);}public Statement createStatement()throws SQLException{return delegate.createStatement();}public PreparedStatement prepareStatement(String s)throws SQLException{return delegate.prepareStatement(s);}public CallableStatement prepareCall(String s)throws SQLException{return delegate.prepareCall(s);}public String nativeSQL(String s)throws SQLException{return delegate.nativeSQL(s);}public void setAutoCommit(boolean b)throws SQLException{delegate.setAutoCommit(b);}public boolean getAutoCommit()throws SQLException{return delegate.getAutoCommit();}public void commit()throws SQLException{delegate.commit();}public void rollback()throws SQLException{delegate.rollback();}public boolean isClosed()throws SQLException{return delegate.isClosed();}public DatabaseMetaData getMetaData()throws SQLException{return delegate.getMetaData();}public void setReadOnly(boolean b)throws SQLException{delegate.setReadOnly(b);}public boolean isReadOnly()throws SQLException{return delegate.isReadOnly();}public void setCatalog(String s)throws SQLException{delegate.setCatalog(s);}public String getCatalog()throws SQLException{return delegate.getCatalog();}public void setTransactionIsolation(int i)throws SQLException{delegate.setTransactionIsolation(i);}public int getTransactionIsolation()throws SQLException{return delegate.getTransactionIsolation();}public SQLWarning getWarnings()throws SQLException{return delegate.getWarnings();}public void clearWarnings()throws SQLException{delegate.clearWarnings();}public Statement createStatement(int a,int b)throws SQLException{return delegate.createStatement(a,b);}public PreparedStatement prepareStatement(String s,int a,int b)throws SQLException{return delegate.prepareStatement(s,a,b);}public CallableStatement prepareCall(String s,int a,int b)throws SQLException{return delegate.prepareCall(s,a,b);}public Map<String,Class<?>>getTypeMap()throws SQLException{return delegate.getTypeMap();}public void setTypeMap(Map<String,Class<?>>m)throws SQLException{delegate.setTypeMap(m);}public void setHoldability(int h)throws SQLException{delegate.setHoldability(h);}public int getHoldability()throws SQLException{return delegate.getHoldability();}public Savepoint setSavepoint()throws SQLException{return delegate.setSavepoint();}public Savepoint setSavepoint(String s)throws SQLException{return delegate.setSavepoint(s);}public void rollback(Savepoint s)throws SQLException{delegate.rollback(s);}public void releaseSavepoint(Savepoint s)throws SQLException{delegate.releaseSavepoint(s);}public Statement createStatement(int a,int b,int d)throws SQLException{return delegate.createStatement(a,b,d);}public PreparedStatement prepareStatement(String s,int a,int b,int d)throws SQLException{return delegate.prepareStatement(s,a,b,d);}public CallableStatement prepareCall(String s,int a,int b,int d)throws SQLException{return delegate.prepareCall(s,a,b,d);}public PreparedStatement prepareStatement(String s,int a)throws SQLException{return delegate.prepareStatement(s,a);}public PreparedStatement prepareStatement(String s,int[]a)throws SQLException{return delegate.prepareStatement(s,a);}public PreparedStatement prepareStatement(String s,String[]a)throws SQLException{return delegate.prepareStatement(s,a);}public Clob createClob()throws SQLException{return delegate.createClob();}public Blob createBlob()throws SQLException{return delegate.createBlob();}public NClob createNClob()throws SQLException{return delegate.createNClob();}public SQLXML createSQLXML()throws SQLException{return delegate.createSQLXML();}public boolean isValid(int t)throws SQLException{return delegate.isValid(t);}public void setClientInfo(String n,String v)throws SQLClientInfoException{delegate.setClientInfo(n,v);}public void setClientInfo(java.util.Properties p)throws SQLClientInfoException{delegate.setClientInfo(p);}public String getClientInfo(String n)throws SQLException{return delegate.getClientInfo(n);}public java.util.Properties getClientInfo()throws SQLException{return delegate.getClientInfo();}public java.sql.Array createArrayOf(String n,Object[]o)throws SQLException{return delegate.createArrayOf(n,o);}public Struct createStruct(String n,Object[]o)throws SQLException{return delegate.createStruct(n,o);}public void setSchema(String s)throws SQLException{delegate.setSchema(s);}public String getSchema()throws SQLException{return delegate.getSchema();}public void abort(Executor e)throws SQLException{delegate.abort(e);}public void setNetworkTimeout(Executor e,int m)throws SQLException{delegate.setNetworkTimeout(e,m);}public int getNetworkTimeout()throws SQLException{return delegate.getNetworkTimeout();}public void close()throws SQLException{delegate.close();}}
}
